const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}));document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('enquiry').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const body='Name: '+d.get('first')+' '+d.get('last')+'\nEmail: '+d.get('email')+'\n\n'+d.get('message');window.location.href='https://wa.me/918600333148?text='+encodeURIComponent('Business enquiry: '+d.get('subject')+'\n\n'+body);document.getElementById('form-status').textContent='WhatsApp has been requested. Tap Send in WhatsApp to deliver your enquiry to Vikram Vaje.';});